input.command:
cd /mnt/c/Projects/biotech_screener/biotech-screener && python3 << 'EOF'
import os
import json

specs_dir = "specs/changes"
specs = {}

for f in os.listdir(specs_dir):
    if f.startswith("spec_") and f.endswith(".md"):
        path = os.path.join(specs_dir, f)
        with open(path, "r") as fp:
            content = fp.read(500)  # First 500 chars
            specs[f] = {
                "status": "UNKNOWN",
                "has_pending": "PENDING" in content or "pending" in content,
                "has_complete": "COMPLETE" in content or "shipped" in content.lower(),
            }

# Show recent ones (Spec 100+)
recent = {k: v for k, v in sorted(specs.items()) if int(k.split('_')[1]) >= 100}
for spec, info in recent.items():
    status = "PENDING" if info["has_pending"] else ("COMPLETE" if info["has_complete"] else "?")
    print(f"{spec}: {status}")
EOF
